# Dados das páginas de estado e cidade. Cada entrada precisa ter texto próprio:
# não copie a economia ou os segmentos de outra região trocando o nome.
# fuso = diferença em horas em relação a Brasília (0, -1, -2).
# prep = preposição usada antes do nome ("no Paraná", "na Bahia", "em Goiás").

def S(slug, nome, uf, prep, regiao, capital, fuso, cidades, economia, segmentos, faq, desc):
    return dict(slug=slug, nome=nome, uf=uf, prep=prep, regiao=regiao, capital=capital, fuso=fuso,
                cidades=cidades, economia=economia, segmentos=segmentos, faq=faq, desc=desc)


